// Gdyby getter/setter mial DOKLADNIE ta sama nazwe co pole, na ktorym
// operuje (np. get szerokosc() { return this.szerokosc; }), powstalby
// nieskonczony cykl:
class ZlyProstokat {
  constructor(szerokosc) {
    this.szerokosc = szerokosc; // to wywoluje SETTER szerokosc, nie zwykle przypisanie!
  }
  get szerokosc() {
    return this.szerokosc; // wywoluje SAM SIEBIE (getter) w nieskonczonosc
  }
  set szerokosc(wartosc) {
    this.szerokosc = wartosc; // wywoluje SAM SIEBIE (setter) w nieskonczonosc
  }
}

// new ZlyProstokat(10); -- RangeError: Maximum call stack size exceeded
// Dlatego uzywa sie ODDZIELNEGO, "wewnetrznego" pola (konwencjonalnie z
// prefiksem _), np. this._szerokosc, ktore getter/setter faktycznie
// odczytuje/zapisuje, unikajac cyklu z SAMYM SOBA.

class Osoba {
  constructor(imie, nazwisko) {
    this._imie = imie;
    this._nazwisko = nazwisko;
  }

  get pelne() {
    return this._imie + " " + this._nazwisko;
  }

  set pelne(napis) {
    const [imie, nazwisko] = napis.split(" ");
    this._imie = imie;
    this._nazwisko = nazwisko;
  }
}

const osoba = new Osoba("Ala", "Nowak");
osoba.pelne = "Jan Kowalski";
console.log(osoba.pelne);    // -> "Jan Kowalski"
console.log(osoba._imie);    // -> "Jan"

class Uczen {
  constructor(wiek) {
    this._wiek = wiek;
  }

  get wiek() {
    return this._wiek;
  }

  set wiek(v) {
    if (v < 0 || v > 120) throw new RangeError("Niepoprawny wiek: " + v);
    this._wiek = v;
  }
}

