u.wiek = 15;
console.log(u.wiek); // -> 15

try {
  u.wiek = 200;
} catch (e) {
  console.log(e.name, e.message); // -> "RangeError" "Niepoprawny wiek: 200"
}
console.log(u.wiek); // -> 15 (nie zmienilo sie)

